contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address other) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (1));
        require(other != msg.sender && c.getBalance(other) == 0);
        c.addToBalance{value: 1}(); if (__ESBMC_reverted()) return;
        uint obs = c.getBalance(other); if (__ESBMC_reverted()) return;
        assert(obs == 0);
    }
    receive() external payable {}
}

